/**
 * Units and net revenue of a product category (incl. subcategories) between two dates (Y-m-d).
 *
 * @return array { qty: int, net: float }
 */
function perfectpixel_get_category_sales( $category_id, $from, $to ) {
	global $wpdb;
	$terms = array_merge( array( (int) $category_id ), array_map( 'intval', get_term_children( $category_id, 'product_cat' ) ) );
	$tt    = array_map( 'intval', get_terms( array( 'taxonomy' => 'product_cat', 'include' => $terms, 'fields' => 'tt_ids', 'hide_empty' => false ) ) );
	if ( ! $tt ) {
		return array( 'qty' => 0, 'net' => 0.0 );
	}
	$row = $wpdb->get_row(
		$wpdb->prepare(
			"SELECT SUM(l.product_qty) AS qty, SUM(l.product_net_revenue) AS net
			FROM {$wpdb->prefix}wc_order_product_lookup l
			INNER JOIN {$wpdb->prefix}wc_order_stats s ON s.order_id = l.order_id
			WHERE s.status IN ('wc-completed','wc-processing')
			AND l.date_created BETWEEN %s AND %s
			AND l.product_id IN ( SELECT object_id FROM {$wpdb->term_relationships} WHERE term_taxonomy_id IN (" . implode( ',', $tt ) . ') )',
			$from . ' 00:00:00',
			$to . ' 23:59:59'
		),
		ARRAY_A
	);
	return array(
		'qty' => (int) ( $row['qty'] ?? 0 ),
		'net' => (float) ( $row['net'] ?? 0 ),
	);
}
